    Recipe(
      id: 'm53156',
      name: 'Arroz al horno (baked rice)',
      description: 'Spanish Pork dish.',
      ingredientKeywords: ['extra virgin olive oil', 'pork belly slices', 'black pudding', 'bacon lardon', 'onion', 'red pepper', 'plum tomatoes', 'garlic clove', 'paprika', 'chilli flakes', 'dried white beans', 'chicken stock', 'thyme', 'paella rice', 'lemon juice'],
      categories: ['Meat'],
      ingredients: [
        '2 tbsp Extra Virgin Olive Oil',
        '800g Pork belly slices',
        '150g Black Pudding',
        '100g Bacon lardon',
        '1 chopped Onion',
        '2 Red Pepper',
        '1 chopped Plum Tomatoes',
        '8 Garlic Clove',
        '4 teaspoons Paprika',
        '1/2 teaspoon Chilli Flakes',
        '200g Dried white beans',
        '1 1/2 L Chicken Stock',
        '6 parts Thyme',
        '375g Paella Rice',
        '1 Lemon Juice',
      ],
      steps: [
        'Heat oven to 200C/180C/gas 6. Heat half the oil in a deep frying or sauté pan (or shallow casserole dish) measuring around 30cm in diameter. Over a high heat, colour the pork belly slices on each side in several batches, then transfer to a bowl. Add the remaining oil to the pan and lower the heat to medium, then add the black pudding and bacon and fry all over for several mins. Remove with a slotted spoon. Fry the onion and peppers for around 10 mins until soft and pale gold, then add the tomato and cook until soft. Add the garlic, smoked paprika and chilli flakes and cook for another 2 mins, then put the pork, black pudding and bacon back in the pan. Add the beans, stock and whichever herb you\'re using, and bring everything to the boil.',
        'Sprinkle the rice around the pork belly, pushing it underneath the stock. Let the stock come to the boil again, season well, then transfer to the oven (leave it uncovered). Cook for 20 mins without stirring, then check to see how the rice is doing. The rice should be tender and the stock absorbed. If it’s not ready, put back in the oven for another 5 mins, then check again. Taste for seasoning.',
        'Squeeze lemon juice over the top and drizzle over some extra virgin olive oil just before serving, if you like.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53495',
      name: 'Amok Trey – Cambodian Fish Curry',
      description: 'Seafood dish.',
      ingredientKeywords: ['fish fillet', 'coconut milk', 'red curry paste', 'fish sauce', 'brown sugar', 'chicken stock', 'egg', 'kaffir lime leaves', 'vegetable oil', 'banana leaves', 'cilantro', 'lime'],
      categories: ['Seafood'],
      ingredients: [
        '1 lb Fish fillet',
        '1 Can Coconut Milk',
        '2 tablespoons Red Curry Paste',
        '1 tablespoon Fish Sauce',
        '1 tsp Brown Sugar',
        '1 cup Chicken Stock',
        '1 Egg',
        '2 Kaffir Lime Leaves',
        '1 tablespoon Vegetable Oil',
        'Handful Banana Leaves',
        'Garnish Cilantro',
        'Garnish Lime',
      ],
      steps: [
        'In a medium bowl, combine the coconut milk, red curry paste, fish sauce, palm sugar, and broth, whisking until smooth—this ensures no lumps in the sauce.',
        'Heat the vegetable oil in a large skillet over medium heat (about 350°F) for 30 seconds until shimmering.',
        'Pour the coconut milk mixture into the skillet and bring it to a gentle simmer, stirring occasionally, which should take about 3-4 minutes.',
        'Add the fish cubes and kaffir lime leaves to the skillet, submerging them fully in the sauce.',
        'Reduce the heat to low, cover the skillet, and let it cook for 10 minutes until the fish is opaque and flakes easily with a fork—avoid overcooking to keep it tender.',
        'Stir in the beaten egg slowly, cooking for 2 more minutes until the sauce thickens slightly, which adds a rich, custard-like texture.',
        'While the curry simmers, prepare the banana leaves by briefly passing them over a gas flame for 10 seconds to make them pliable, or use parchment paper as a handy alternative.',
        'Spoon the curry into the center of each banana leaf square, folding the edges to form a tight packet to trap steam.',
        'Place the packets in a steamer basket over boiling water and steam for 10 minutes until heated through and fragrant.',
        'Carefully unwrap the packets and garnish with fresh cilantro and lime wedges before serving',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53284',
      name: 'Algerian Bouzgene Berber Bread with Roasted Pepper Sauce',
      description: 'Algerian Side dish.',
      ingredientKeywords: ['red pepper', 'tomato', 'olive oil', 'garlic', 'jalapeno', 'salt', 'semolina', 'salt', 'water', 'olive oil', 'olive oil'],
      categories: [],
      ingredients: [
        '2 Red Pepper',
        '4 Tomato',
        '1 tablespoon Olive Oil',
        '4 Cloves Chopped Garlic',
        '1 chopped Jalapeno',
        'To taste Salt',
        '2 Lbs Semolina',
        '1 1/2 tsp Salt',
        '3 Cups Water',
        '4 tablespoons Olive Oil',
        '6 tablespoons Olive Oil',
      ],
      steps: [
        'Preheat your oven\'s broiler. Place red bell peppers and tomatoes on a baking sheet, and roast under the broiler for about 8 minutes, turning occasionally. This should blacken the skin and help it peel off more easily. Cool, then scrape the skins off of the tomatoes and peppers, and place them in a large bowl. Remove cores and seeds from the bell peppers.',
        'Heat 1 tablespoon of olive oil in a skillet over medium heat. Add the jalapenos and garlic, and cook until tender, stirring frequently. Remove from heat, and transfer the garlic and jalapeno to the bowl with the tomatoes and red peppers. Using two sharp steak knives (one in each hand), cut up the tomatoes and peppers to a coarse and soupy consistency. Stir, and set sauce aside.',
        'Place the semolina in a large bowl, and stir in salt and 4 tablespoons of olive oil. Gradually add water while mixing and squeezing with your hand until the dough holds together without being sticky or dry, and molds easily with the hand. Divide into 6 pieces and form into balls.',
        'For each round, heat 1 tablespoon of olive oil in a large heavy skillet over medium heat. Roll out dough one round at a time, to no thicker than 1/4 inch. Fry in the hot skillet until dark brown spots appear on the surface, and they are crispy. Remove from the skillet, and wrap in a clean towel while preparing the remaining flat breads.',
        'To eat the bread and sauce, break off pieces of the bread, and scoop them into the sauce. It will slide off, but just keep reaching in!',
      ],
      prepMinutes: 30,
    ),
    Recipe(
