    Recipe(
      id: 'm53329',
      name: 'Arepa pelua',
      description: 'Venezuela Beef dish.',
      ingredientKeywords: ['beef', 'onion', 'red pepper', 'garlic', 'cumin', 'oregano', 'paprika', 'beef stock', 'water', 'salt', 'cheese', 'extra virgin olive oil'],
