    Recipe(
      id: 'm52835',
      name: 'Fettucine alfredo',
      description: 'Italian Pasta dish.',
      ingredientKeywords: ['clotted cream', 'butter', 'corn flour', 'parmesan cheese', 'nutmeg', 'fettuccine', 'parsley'],
      categories: ['Bakery', 'Dairy'],
