    Recipe(
      id: 'm53496',
      name: 'Bai Sach Chrouk – Grilled Pork with Rice',
      description: 'Pork dish.',
      ingredientKeywords: ['pork shoulder', 'coconut milk', 'soy sauce', 'oyster sauce', 'honey', 'garlic', 'black pepper', 'jasmine rice', 'water', 'vegetable oil', 'cucumber', 'cilantro leaves'],
      categories: ['Meat'],
      ingredients: [
        '650g Pork Shoulder',
        '1/4 cup Coconut Milk',
        '3  tablespoons Soy Sauce',
        '2 tablespoons Oyster Sauce',
        '2 tablespoons Honey',
        '4 cloves Garlic',
        '1 tsp Black Pepper',
        '2 cups Jasmine Rice',
        '4 cups Water',
        '1 tablespoon Vegetable Oil',
        '1 sliced Cucumber',
        'Garnish Cilantro Leaves',
      ],
      steps: [
        'In a large bowl, combine the coconut milk, soy sauce, oyster sauce, honey, minced garlic, and black pepper to make the marinade.',
        'Add the thinly sliced pork shoulder to the marinade, ensuring each piece is fully coated, then cover and refrigerate for at least 30 minutes to allow the flavors to penetrate.',
        'While the pork marinates, rinse the jasmine rice under cold water until the water runs clear to remove excess starch, which helps prevent clumping.',
        'In a medium pot, combine the rinsed rice and 4 cups of water, bring to a boil over high heat, then reduce to a simmer, cover, and cook for 15 minutes until the water is absorbed and the rice is tender.',
        'Heat a grill pan or outdoor grill to medium-high heat (about 400°F) and lightly brush with vegetable oil to prevent sticking.',
        'Remove the pork from the marinade, shaking off any excess, and place it on the hot grill, cooking for 3-4 minutes per side until nicely charred and cooked through with an internal temperature of 145°F.',
        'Tip: Avoid overcrowding the grill pan to ensure even browning and proper caramelization of the marinade.',
        'Once the pork is grilled, let it rest for 5 minutes before slicing to retain its juices and tenderness.',
        'Tip: If you prefer a saucier dish, simmer the leftover marinade in a small saucepan for 5 minutes until slightly thickened and drizzle it over the pork.',
        'Fluff the cooked rice with a fork to separate the grains and serve it warm alongside the grilled pork slices.',
        'Arrange the thinly sliced cucumber and fresh cilantro leaves on top as a refreshing garnish.',
        'Tip: For an extra kick, serve with a side of pickled vegetables or a squeeze of lime juice to balance the rich, savory flavors.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53147',
      name: 'Arroz con gambas y calamar',
      description: 'Spanish Seafood dish.',
      ingredientKeywords: ['raw king prawns', 'olive oil', 'onion', 'bay leaf', 'saffron', 'paella rice', 'tomato puree', 'white wine', 'seafood stock', 'squid'],
      categories: ['Seafood'],
      ingredients: [
        '24 Raw King Prawns',
        '2 tbsp Olive Oil',
        '1 small Onion',
        '1 Bay Leaf',
        '1 pinch Saffron',
        '450g Paella Rice',
        '2 teaspoons Tomato Puree',
        '200ml White Wine',
        '650ml Seafood stock',
        '3 Medium Squid',
      ],
      steps: [
        'Peel and devein most of the prawns (a fishmonger should be able to do this for you), keeping a few whole for decoration, if you like. Heat the olive oil in a large frying pan or shallow flameproof casserole over a medium-low heat and fry the onion for 5 mins until softened. Add the bay leaf, saffron, rice and tomato purée, and cook for 1-2 mins more, stirring.',
        'Pour in the wine and bubble for 1-2 mins, then pour in the seafood stock and 150ml water. Cook for 5 mins, then add the squid, season well and stir to combine. Bring to the boil, then cover and reduce the heat to a gentle simmer. Cook for 12 mins more, adding a little more water if the mixture starts to look dry.',
        'Uncover the pan and stir through the peeled prawns, then arrange any whole prawns on top of the rice mixture. Cover again and simmer for a further 5-6 mins until the prawns are pink and cooked through. Leave to stand for a couple of minutes before serving from the pan.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53282',
      name: 'Algerian Carrots',
      description: 'Algerian Side dish.',
      ingredientKeywords: ['water', 'carrots', 'olive oil', 'salt', 'black pepper', 'ground cinnamon', 'ground cumin', 'garlic', 'thyme', 'bay leaf', 'lemon juice'],
