    Recipe(
      id: 'm53099',
      name: 'Aussie Burgers',
      description: 'Australian Beef dish.',
      ingredientKeywords: ['lean minced steak', 'cooked beetroot', 'naan bread', 'rocket', 'soured cream and chive dip'],
      categories: ['Bakery', 'Dairy', 'Meat'],
      ingredients: [
