    Recipe(
      id: 'm52893',
      name: 'Apple & Blackberry Crumble',
      description: 'British Dessert dish.',
      ingredientKeywords: ['plain flour', 'caster sugar', 'butter', 'braeburn apples', 'butter', 'demerara sugar', 'blackberries', 'cinnamon', 'ice cream'],
      categories: ['Bakery', 'Dairy'],
