    Recipe(
      id: 'm53457',
      name: 'Barbados Pepperpot',
      description: 'Beef dish.',
      ingredientKeywords: ['pigs trotters', 'oxtail', 'lime juice', 'garlic', 'scotch bonnet', 'onion', 'cinnamon stick', 'cloves', 'sugar', 'salt', 'basil', 'thyme', 'beef'],
