    Recipe(
      id: 'm53380',
      name: 'Apple cake',
      description: 'Netherlands Dessert dish.',
      ingredientKeywords: ['eggs', 'sugar', 'self-raising flour', 'melted butter', 'vanilla extract', 'ground cinnamon', 'apples', 'salt', 'ground sugar'],
