    Recipe(
      id: 'm52844',
      name: 'Lasagne',
      description: 'Italian Pasta dish.',
      ingredientKeywords: ['olive oil', 'bacon', 'onion', 'celery', 'carrots', 'garlic', 'minced beef', 'tomato puree', 'chopped tomatoes', 'honey', 'lasagne sheets', 'creme fraiche', 'mozzarella balls', 'parmesan cheese', 'basil leaves'],
      categories: ['Dairy', 'Meat'],
      ingredients: [
        '1 tblsp Olive Oil',
        '2 Bacon',
        '1 finely chopped Onion',
        '1 Stick Celery',
        '1 medium Carrots',
        '2 cloves chopped Garlic',
        '500g Minced Beef',
        '1 tbls Tomato Puree',
        '800g Chopped Tomatoes',
        '1 tblsp Honey',
        '500g Lasagne Sheets',
        '400ml Creme Fraiche',
        '125g Mozzarella Balls',
        '50g Parmesan Cheese',
        'Topping Basil Leaves',
      ],
      steps: [
        'Heat the oil in a large saucepan. Use kitchen scissors to snip the bacon into small pieces, or use a sharp knife to chop it on a chopping board. Add the bacon to the pan and cook for just a few mins until starting to turn golden. Add the onion, celery and carrot, and cook over a medium heat for 5 mins, stirring occasionally, until softened.',
        'Add the garlic and cook for 1 min, then tip in the mince and cook, stirring and breaking it up with a wooden spoon, for about 6 mins until browned all over.',
        'Stir in the tomato purée and cook for 1 min, mixing in well with the beef and vegetables. Tip in the chopped tomatoes. Fill each can half full with water to rinse out any tomatoes left in the can, and add to the pan. Add the honey and season to taste. Simmer for 20 mins.',
        'Heat oven to 200C/180C fan/gas 6. To assemble the lasagne, ladle a little of the ragu sauce into the bottom of the roasting tin or casserole dish, spreading the sauce all over the base. Place 2 sheets of lasagne on top of the sauce overlapping to make it fit, then repeat with more sauce and another layer of pasta. Repeat with a further 2 layers of sauce and pasta, finishing with a layer of pasta.',
        'Put the crème fraîche in a bowl and mix with 2 tbsp water to loosen it and make a smooth pourable sauce. Pour this over the top of the pasta, then top with the mozzarella. Sprinkle Parmesan over the top and bake for 25–30 mins until golden and bubbling. Serve scattered with basil, if you like.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53468',
      name: 'Belgian Stoemp',
      description: 'Pork dish.',
      ingredientKeywords: ['sausages', 'potatoes', 'savoy cabbage', 'garlic', 'parsley', 'onion', 'unsalted butter', 'beer', 'whole milk', 'nutmeg', 'pepper', 'salt'],
      categories: ['Dairy', 'Meat'],
      ingredients: [
        '2 Sausages',
        '450g Potatoes',
        '200g Savoy Cabbage',
        '3 cloves Garlic',
        '1 Handfull Parsley',
        '1 small finely diced Onion',
        '3  tablespoons Unsalted Butter',
        '1 cup Beer',
        '60ml Whole Milk',
        'Pinch Nutmeg',
        'Pinch Pepper',
        'Pinch Salt',
      ],
      steps: [
        'Add the chopped potatoes and garlic to a high pan and fill it with tap water until the potatoes are fully submerged.',
        'Add some salt. Then place the pan over high heat and bring the potatoes to a boil. Cook them until tender. In the meantime rinse and drain the savoy cabbage. Slice it up finely.',
        'Add a tablespoon of butter to a large non-stick pan. Place it over medium-high heat. Once melted, add the savoy cabbage. Season with a pinch of pepper and salt.',
        'Stir fry the cabbage for 15 to 20 minutes or until the cabbage is soft and tender. Then turn the heat off and take the cabbage off the heat. In the meantime, pan fry the sausages (or sliced bacon if you are using both) in a non-stick pan in a tablespoon of butter or oil until golden brown and cooked through.',
        'Transfer the sausages (and bacon) to a plate and cover with a lid or tinfoil to keep the meat warm. In the same greasy pan, add the sliced onion and extra butter and cook it gently over medium heat for 10 minutes until softened. (I often add diced bacon as well, if I only serve the stoemp with sausages.)',
        'Then add the beer and turn the heat up. Let the beer reduce until you get a nice beer and onion sauce (you can add a little flour or sauce thickener if you like). Add the pan fried meat back to the pan and cover to keep warm.',
        'Drain the cooked potatoes and garlic, add them back to the pan you cooked them in together with the pan fried cabbage and chopped parsley. Sprinkle with some pepper, salt and nutmeg. Also add the milk and the rest of the unsalted butter.',
        'Mash the potatoes, parsley and cabbage up. Add extra butter or milk if necessary. Also check the seasoning and add extra pepper, nutmeg or salt to taste if necessary. Scoop the cabbage mash onto plates and top with the pan fried sausages (and bacon). Drizzle with the beer and onion sauce. Serve hot.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
