    Recipe(
      id: 'm52807',
      name: 'Baingan Bharta',
      description: 'India Vegetarian dish.',
      ingredientKeywords: ['aubergine', 'onion', 'tomatoes', 'garlic', 'green chilli', 'red chilli powder', 'oil', 'coriander leaves', 'salt'],
      categories: ['Produce'],
      ingredients: [
        '1 large Aubergine',
        '½ cup Onion',
        '1 cup Tomatoes',
        '6 cloves Garlic',
        '1 Green Chilli',
        '¼ teaspoon Red Chilli Powder',
        '1.5 tablespoon Oil',
        '1 tablespoon chopped Coriander Leaves',
        'as required salt',
      ],
      steps: [
        'Rinse the baingan (eggplant or aubergine) in water. Pat dry with a kitchen napkin. Apply some oil all over and',
        'keep it for roasting on an open flame. You can also grill the baingan or roast in the oven. But then you won\'t get',
        'the smoky flavor of the baingan. Keep the eggplant turning after a 2 to 3 minutes on the flame, so that its evenly',
        'cooked. You could also embed some garlic cloves in the baingan and then roast it.',
        'Roast the aubergine till its completely cooked and tender. With a knife check the doneness. The knife should slid',
        'easily in aubergines without any resistance. Remove the baingan and immerse in a bowl of water till it cools',
        'down.',
        'You can also do the dhungar technique of infusing charcoal smoky flavor in the baingan. This is an optional step.',
        'Use natural charcoal for this method. Heat a small piece of charcoal on flame till it becomes smoking hot and red.',
        'Make small cuts on the baingan with a knife. Place the red hot charcoal in the same plate where the roasted',
        'aubergine is kept. Add a few drops of oil on the charcoal. The charcoal would begin to smoke.',
        'As soon as smoke begins to release from the charcoal, cover the entire plate tightly with a large bowl. Allow the',
        'charcoal smoke to get infused for 1 to 2 minutes. The more you do, the more smoky the baingan bharta will',
        'become. I just keep for a minute. Alternatively, you can also do this dhungar method once the baingan bharta is',
        'cooked, just like the way we do for Dal Tadka.',
        'Peel the skin from the roasted and smoked eggplant.',
        'Chop the cooked eggplant finely or you can even mash it.',
        'In a kadai or pan, heat oil. Then add finely chopped onions and garlic.',
        'Saute the onions till translucent. Don\'t brown them.',
        'Add chopped green chilies and saute for a minute.',
        'Add the chopped tomatoes and mix it well.',
        'Bhuno (saute) the tomatoes till the oil starts separating from the mixture.',
        'Now add the red chili powder. Stir and mix well.',
        'Add the chopped cooked baingan.',
        'Stir and mix the chopped baingan very well with the onion­tomato masala mixture.',
        'Season with salt. Stir and saute for some more 4 to 5 minutes more.',
        'Finally stir in the coriander leaves with the baingan bharta or garnish it with them. Serve Baingan Bharta with',
        'phulkas, rotis or chapatis. It goes well even with bread, toasted or grilled bread and plain rice or jeera rice.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53366',
      name: 'Beef and Broccoli Stir-Fry',
      description: 'Chinese Beef dish.',
      ingredientKeywords: ['soy sauce', 'dry sherry', 'cornstarch', 'black pepper', 'sirloin steak', 'oyster sauce', 'dry sherry', 'soy sauce', 'chicken stock', 'broccoli', 'high heat cooking oil', 'garlic', 'cornstarch', 'water'],
      categories: ['Meat'],
      ingredients: [
        '1 tsp Soy Sauce',
        '1 tsp Dry sherry',
        '1/2 tsp Cornstarch',
        '1/8 teaspoon Black Pepper',
        '1 lb Sirloin steak',
        '2 tablespoons Oyster Sauce',
        '1 tsp Dry sherry',
        '1 tablespoon Soy Sauce',
        '1/4 cup Chicken Stock',
        '1 lb Broccoli',
        '2 tablespoons High Heat Cooking Oil',
        '2 cloves minced Garlic',
        '1 tsp Cornstarch',
        '1 tablespoon Water',
      ],
      steps: [
        'Marinate the beef:',
        'Stir together the beef marinade ingredients (1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper) in a medium bowl.',
        'Add the beef slices and stir until coated. Let stand for 10 minutes.',
        'Prepare the sauce:',
        'Stir together the sauce ingredients (2 tablespoons oyster sauce, 1 teaspoon Chinese rice wine, 1 teaspoon soy sauce, 1/4 cup chicken broth) in a small bowl. Set aside.',
        'Blanch or steam the broccoli:',
        'Bring a pot of water to a boil. Add the broccoli and cook until crisp-tender, about 2 minutes. Drain thoroughly.',
        'Stir-fry the beef:',
        'Heat a large frying pan or wok over high heat until a bead of water sizzles and instantly evaporates upon contact. Add the cooking oil and swirl to coat.',
        'Add the beef and immediately spread it out all over the surface of the wok or pan in a single layer (preferably not touching).',
        'Let the beef fry undisturbed for 1 minute. Flip the beef slices over, add the garlic to the pan, and fry for an additional 30 seconds to 1 minute until no longer pink.',
        'Add the sauce, cornstarch, and broccoli:',
        'Pour in the sauce and the cornstarch slurry (1 teaspoon cornstarch dissolved in 1 tablespoon of water). Stir until the sauce boils and thickens, about 30 seconds. Stir in the broccoli.',
        'Serve immediately, with steamed rice or on its own.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm52957',
      name: 'Fruit and Cream Cheese Breakfast Pastries',
      description: 'United States Breakfast dish.',
      ingredientKeywords: ['cream cheese', 'sugar', 'vanilla extract', 'flour', 'puff pastry', 'strawberries', 'raspberries', 'blackberries'],
      categories: ['Bakery', 'Dairy'],
      ingredients: [
        '1 1/4 oz Cream Cheese',
        '1 1/4 cup Sugar',
        '1 teaspoon Vanilla Extract',
        'Flour',
        '2 Puff Pastry',
        'Strawberries',
        'Raspberries',
        'Blackberries',
      ],
      steps: [
        'Preheat oven to 400ºF (200ºC), and prepare two cookie sheets with parchment paper. In a bowl, mix cream cheese, sugar, and vanilla until fully combined. Lightly flour the surface and roll out puff pastry on top to flatten. Cut each sheet of puff pastry into 9 equal squares. On the top right and bottom left of the pastry, cut an L shape approximately ½ inch (1 cm) from the edge.',
        'NOTE: This L shape should reach all the way down and across the square, however both L shapes should not meet at the ends. Your pastry should look like a picture frame with two corners still intact.',
        'Take the upper right corner and fold down towards the inner bottom corner. You will now have a diamond shape.',
        'Place 1 to 2 teaspoons of the cream cheese filling in the middle, then place berries on top.',
        'Repeat with the remaining pastry squares and place them onto the parchment covered baking sheet.',
        'Bake for 15-20 minutes or until pastry is golden brown and puffed.',
        'Enjoy!',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53161',
      name: 'Chicken & chorizo rice pot',
      description: 'Spanish Chicken dish.',
