    Recipe(
      id: 'm53094',
      name: 'Baba Ghanoush',
      description: 'Syrian Side dish.',
      ingredientKeywords: ['egg plants', 'garlic', 'kosher salt', 'lemon', 'tahini', 'extra virgin olive oil', 'greek yogurt', 'cayenne pepper', 'mint', 'parsley'],
      categories: ['Dairy'],
      ingredients: [
        '4 large Egg Plants',
        '2 cloves Garlic',
        '2 teaspoons Kosher Salt',
        '1 Lemon',
        '3  tablespoons Tahini',
        '3  tablespoons Extra Virgin Olive Oil',
        '2 tablespoons Greek Yogurt',
        '1 pinch Cayenne Pepper',
        '1 Leaf Mint',
        '2 tablespoons Parsley',
      ],
      steps: [
        'Preheat an outdoor grill for medium-high heat and lightly oil the grate. Prick the surface of the skin of eggplants several times with the tip of a knife.',
        'Place eggplants directly on grill. Turn frequently with tongs while skin chars. Cook until eggplants have collapsed and are very soft, 25 to 30 minutes. Transfer to a bowl and cover tightly with aluminum foil and allow to cool, about 15 minutes.',
        'When eggplants are cool enough to handle, split them in half and scrape flesh into a colander placed over a bowl. Drain 5 or 10 minutes.',
        'Transfer eggplant to mixing bowl. Add crushed garlic and salt; mash until creamy but with a little texture, about 5 minutes. Whisk in lemon juice, tahini, olive oil, and cayenne pepper. Stir in yogurt.',
        'Cover bowl with plastic wrap and refrigerate until completely chilled. Stir in mint and parsley, and taste to adjust seasonings before serving.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53402',
      name: 'Mantu Afghan Dumpling',
      description: 'Starter dish.',
      ingredientKeywords: ['plain flour', 'water', 'lamb', 'green chilli', 'onions', 'black pepper', 'vegetable oil', 'tomato puree', 'strained yoghurt', 'coriander'],
      categories: ['Bakery', 'Dairy', 'Meat'],
      ingredients: [
        '450g Plain Flour',
        '225ml Water',
        '450g Lamb',
        '1 Green Chilli',
        '450g Onions',
        '2 tblsp Black Pepper',
        '1 tablespoon Vegetable Oil',
        '1 tablespoon Tomato Puree',
        '425ml Strained Yoghurt',
        'Pinch Coriander',
      ],
      steps: [
        'To prepare the dough, sift the flour with 1tsp of salt into a mixing bowl. Slowly mix in as much of the water is required, until a stiff dough is formed. Knead on a clean work surface for 5-10 minutes, until the dough is elastic and shiny. Cover with a damp cloth and set aside for about an hour.',
        'Put the chopped lamb, onions, chilli, 1 tsp salt, ground pepper and spices in a bowl and mix thoroughly.',
        'Divide the dough into 4 small balls, and roll out to a thickness of 1.5mm, cutting into 10cm squares. Into each square, place 1 heaped teaspoon of the lamb mixture.',
        'Take two opposite corners and bring them to join in the centre by nipping together firmly between your fingers, and then bring together to other two corners in the same manner. Note that the mantu should not be entirely closed, as the steam has to be penetrate and cook the filling!',
        'Using fat to grease the shelves of the steamer, place your mantu so that there is a small space between each one. Steam for 30-45 minutes over a medium heat.',
        'Meanwhile, make the tomato sauce. Heat the oil in a pan, add tomato puree, and bring to the boil. Stir and simmer on a low heat until the mantu are ready.',
        'Remove the mantu carefully from the steamer and place on a large, warm dish. Spoon the tomato sauce over the top, followed by the strained yoghurt, and sprinkle with chopped coriander to garnish.',
      ],
      prepMinutes: 30,
    ),
