    Recipe(
      id: 'm53449',
      name: 'Kelem dolmasi',
      description: 'Lamb dish.',
      ingredientKeywords: ['lamb mince', 'cabbage', 'onion', 'salt', 'pepper', 'turmeric', 'cinnamon', 'cilantro', 'dill', 'rice', 'chickpeas', 'lamb fat', 'tomato puree', 'water'],
      categories: ['Meat'],
      ingredients: [
        '500g Lamb Mince',
        '1 large Cabbage',
        '8 oz Onion',
        'Pinch Salt',
        'Pinch Pepper',
        '1/2 tsp Turmeric',
        '1/2 tsp Cinnamon',
        '2 tablespoons Cilantro',
        '2 tablespoons Dill',
        '2 oz Rice',
        '2 oz Chickpeas',
        '3 oz Lamb Fat',
        '1 tablespoon Tomato Puree',
        '3  tablespoons Water',
      ],
      steps: [
        'First boil the rice for eight minutes. Meanwhile, peel and finely chop the onion. Then chop the herbs.',
        'The recipe didn\'t really say what to do with the chickpeas (also known of course as garbanzo beans), beyond soaking them overnight and rinsing them. I used canned chickpeas, since I\'ve never actually seen them dried. I decided to chop/mash them slightly so they would better incorporate into the filling.',
        'Chickpeas (or garbanzo beans) roughly chopped',
        'Now mince the lamb (I used my mini food processor). Here\'s where I ran into another problem: what to do with the lamb fat this recipe calls for? Mince it? Melt it? Does lamb fat even melt? I decided to mince mine. Thankfully, my husband doesn\'t actually read this blog because he\'d be horrified if he knew I put fat in the dolma on purpose.',
        'Minced lamb and its good friend, minced fat. Ew.',
        'The ingredients for the dolma stuffing include onion, cilantro, chickpeas and turmeric.',
        'Anyway, now get your hands into all that slimy raw meat and mix in the onion, spices, chickpeas, rice, chopped herbs and fat. Add a little salt and pepper for good measure. In fact, based on my results I would say to err on the side of a little extra salt and pepper.',
        'Mix well with your hands until the stuffing looks something like this.',
        'Fill the biggest saucepan you own with salted water and bring it to a boil over high heat. Now pull the outer leaves off of the cabbage (save them) and drop the rest of it, whole, into the water. Let it boil for three or four minutes, turning it if the water level isn\'t quite high enough to completely cover it.',
        'The reason you are doing this is because it\'s difficult to get whole cabbage leaves off of an American cabbage. The cabbages you typically buy in our supermarkets come in very tight round balls, and because the leaves are crispy they will snap and crack when you try to pull them off in an un-blanched state. Blanching them for a few minutes makes it so they will come right off without tearing.',
        'Now carefully take the cabbage out of the water (but keep the water boiling) and let it cool for a minute or two so you don\'t burn your fingers. Carefully pull the leaves off the cabbage, cutting them at the base if you have to do so to loosen them. Try to get them off in one piece. If the inner leaves are still crispy, return the cabbage to the boiling water for another three or four minutes. Repeat until all of the useable leaves are free.',
        'Blanched cabbage leaves',
        'Now put the leaves on a cutting board and cut out the tough stalks (save them). Cut the largest leaves in half.',
        'Remove the tough inner stalk and set aside. Cut larger leaves in two.',
        'Put a heaping tablespoon of the filling in the middle of each leaf, making a short cylinder shape. Fold the ends over the filling, then roll tightly (as if you are making a tiny burrito).',
        'This is not much of a cylinder, but you get the idea.',
        'Fold the edges over ...',
        'Then roll, as if you were making a really small burrito.',
        'Your finished dolma should look kind of like this, only without the hole in the middle.',
        'Put all of the discarded cabbage leaves, stalks etc. into the bottom of a stockpot. I know, this seems a little strange. What you\'re basically going to be doing is steaming the dolma, with the discarded cabbage pieces forming the base of your steamer. Carefully place the dolma on the bed of cabbage leaves.',
        'These dolma are resting on top of discarded cabbage leaves.',
        'Add water to the stockpot up to about the top of the discarded leaves. Don\'t cover the dolma.',
        'Now here\'s where you have to get a bit creative. The dolma needs to be weighted down so it doesn\'t unwrap during cooking. I used a metal pie pan, and then I put my mortar on top of it. You could also use a dessert plate with something heavy on top of it, but it would need to be an oven-safe one.',
        'The dolma need to be weighted down during cooking so they don\'t unwrap. Just improvise.',
        'Bring the water to a boil, then simmer for 25 minutes.You might have to use your ears to figure out if the water is actually boiling; I personally couldn\'t see what was in my pot after I weighted it down.',
        'Meanwhile, make a simple tomato sauce out of the tomato paste and water. Heat it up for a few minutes over a medium flame. After the dolma have been cooking for 25 minutes, pour the sauce over them and cook for another five minutes.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm52907',
      name: 'Duck Confit',
      description: 'France Miscellaneous dish.',
      ingredientKeywords: ['sea salt', 'bay leaf', 'garlic', 'thyme', 'duck legs', 'white wine'],
      categories: [],
      ingredients: [
        'Handful Sea Salt',
        '4 Bay Leaf',
        '4 cloves Garlic',
        'Handful Thyme',
        '4 Duck Legs',
        '100ml White Wine',
      ],
      steps: [
        'The day before you want to make the dish, scatter half the salt, half the garlic and half of the herbs over the base of a small shallow dish. Lay the duck legs, skin-side up, on top, then scatter over the remaining salt, garlic and herbs. Cover the duck and refrigerate overnight. This can be done up to 2 days ahead.',
        'Pour the wine into a saucepan that will snugly fit the duck legs in a single layer. Brush the salt off the duck legs and place them, skin-side down, in the wine. Cover the pan with a lid and place over a medium heat. As soon as the wine starts to bubble, turn the heat down to the lowest setting and cook for 2 hours, checking occasionally that the liquid is just barely simmering. (If you own a heat diffuser, it would be good to use it here.) After 2 hours, the duck legs should be submerged in their own fat and the meat should feel incredibly tender when prodded. Leave to cool.',
        'The duck legs are now cooked and can be eaten immediately – or you can follow the next step if you like them crisp. If you are preparing ahead, pack the duck legs tightly into a plastic container or jar and pour over the fat, but not the liquid at the bottom of the pan. Cover and leave in the fridge for up to a month, or freeze for up to 3 months. The liquid you are left with makes a tasty gravy, which can be chilled or frozen until needed.',
        'To reheat and crisp up the duck legs, heat oven to 220C/fan 200C/gas 7. Remove the legs from the fat and place them, skin-side down, in an ovenproof frying pan. Roast for 30-40 mins, turning halfway through, until brown and crisp. Serve with the reheated gravy, a crisp salad and some crisp golden ptoatoes.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53504',
      name: 'Macaroni Pudding',
      description: 'Pasta dish.',
      ingredientKeywords: ['macaroni', 'evaporated milk', 'water', 'sugar', 'salt', 'eggs', 'butter', 'raisins', 'nutmeg', 'vanilla'],
      categories: ['Dairy'],
      ingredients: [
        '4 cups Macaroni',
        '4 cups Evaporated Milk',
        '1 cup Water',
        '3 Cups Sugar',
        '2 tsp Salt',
        '4 Eggs',
        '1/4 cup Butter',
        '1 cup Raisins',
        '2 1/2 Tsp Nutmeg',
        '2 tablespoons Vanilla',
      ],
      steps: [
        'Add macaroni to large pan with sufficient water to cover (approximately 4 cups). Add salt and bring to boil until tender (approximately 25 -30 minutes). Meanwhile, beat eggs and sugar together, then add vanilla and nutmeg. Mix well and set aside. In a separate medium sauce pan, heat evaporated milk plus 1 cup of water and butter to almost a boiling point. Remove from heat and add to sugar mixture. Drain cooked macaroni. Add macaroni and raisins to the milk mixture and stir well. (This mixture will have quite a bit of liquid, but this will form a nice custard textured pudding once baked.)',
        'Grease a large baking dish with butter or margarine, add the macaroni mixture and sprinkle with additional nutmeg. Bake at 350° F for 1 hour or until golden brown. (Pudding should be firm enough to cut, but moist and not dry).',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53036',
      name: 'Boxty Breakfast',
      description: 'Irish Pork dish.',
      ingredientKeywords: ['potatoes', 'spring onions', 'plain flour', 'egg white', 'milk', 'bicarbonate of soda', 'butter', 'vegetable oil', 'cherry tomatoes', 'bacon', 'egg'],
      categories: ['Bakery', 'Dairy', 'Meat'],
      ingredients: [
        '4 large Potatoes',
        '1  bunch Spring Onions',
        '100g Plain Flour',
        '1 Egg White',
        '150ml Milk',
        '1 tsp Bicarbonate Of Soda',
        '3 tbs Butter',
        '2 tbs Vegetable Oil',
        '6 Cherry Tomatoes',
        '12 Bacon',
        '6 Egg',
      ],
      steps: [
        'Before you start, put your oven on its lowest setting, ready to keep things warm. Peel the potatoes, grate 2 of them, then set aside. Cut the other 2 into large chunks, then boil for 10-15 mins or until tender. Meanwhile, squeeze as much of the liquid from the grated potatoes as you can using a clean tea towel. Mash the boiled potatoes, then mix with the grated potato, spring onions and flour.',
        'Whisk the egg white in a large bowl until it holds soft peaks. Fold in the buttermilk, then add the bicarbonate of soda. Fold into the potato mix.',
        'Heat a large non-stick frying pan over a medium heat, then add 1 tbsp butter and some of the oil. Drop 3-4 spoonfuls of the potato mixture into the pan, then gently cook for 3-5 mins on each side until golden and crusty. Keep warm on a plate in the oven while you cook the next batch, adding more butter and oil to the pan before you do so. You will get 16 crumpet-size boxty from the mix. Can be made the day ahead, drained on kitchen paper, then reheated in a low oven for 20 mins.',
        'Heat the grill to medium and put the tomatoes in a heavy-based pan. Add a good knob of butter and a little oil, then fry for about 5 mins until softened. Grill the bacon, then pile onto a plate and keep warm. Stack up the boxty, bacon and egg, and serve the tomatoes on the side.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53451',
      name: 'Bangladeshi fish curry with daikon',
      description: 'Seafood dish.',
      ingredientKeywords: ['white fish', 'daikon radish', 'vegetable oil', 'garlic', 'onion', 'salt', 'ground turmeric', 'ground coriander', 'chilli powder', 'green chilli', 'coriander leaves', 'lime'],
      categories: ['Seafood'],
      ingredients: [
        '450g White Fish',
        '450g Daikon Radish',
        '4 tablespoons Vegetable Oil',
        '4 cloves Garlic',
        '1 medium Onion',
        '2 tsp Salt',
        '1 tsp Ground Turmeric',
        '2 tsp Ground Coriander',
        '2 tsp Chilli Powder',
        '2 Green Chilli',
        'Handful Coriander Leaves',
        '1 Lime',
      ],
      steps: [
        'If you are using rohu fish it will usually be frozen. Soak it in cold water for 30-45 minutes to defrost and while still a little firm, descale and cut each steak into quarters and wash in cold saltwater a few times. Drain and set aside. If using an alternative such as cod, cut into 2 ½ inch chunks then rinse, drain and set aside',
        'Top and tail the daikon and peel using a potato peeler. Cut in half widthways then cut each half down the middle, lengthways. Now slice into 2cm-thick half-moon pieces. Rinse and set aside',
        'Place a large, shallow saucepan over a medium heat and add the oil. When the oil is hot add the crushed garlic and stir for a minute until pale golden',
        'Add the onion paste and salt and cook for 3-5 minutes, until the onion softens and becomes translucent, stirring occasionally',
        'Pour in 200ml of water then cover and cook for 10 minutes, stirring once or twice',
        'After 10 minutes add the ground spices and stir for a couple of minutes so that the spices cook through. Cover and cook for 5 minutes over a low heat then stir in the daikon. After a minute or so add 200ml of water. Cover and cook for 10 minutes on a medium heat',
        'Add the fish pieces to the pan and mix thoroughly so that the fish is coated in the spices. Gently shake the pan and cover and cook for 5 minutes on medium heat. It is very important not to stir the pot after this stage',
        'Meanwhile, boil some water. After the 5 minutes are over carefully pour 500ml hot water into the pan. When doing this pour into the sides of the pan so that you don’t pour boiling water directly onto the fish',
        'Give the pan a gentle shake then cover and simmer over high heat for 15 minutes. Add the chopped coriander and chillies and continue cooking for another 5 minutes then turn off the heat. Serve immediately with rice and the lime wedges',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53456',
      name: 'Bajan Salt Bread Recipe',
      description: 'Side dish.',
      ingredientKeywords: ['yeast', 'sugar', 'salt', 'vegetable oil', 'flour', 'warm water'],
      categories: ['Bakery'],
      ingredients: [
        '2 tubs Yeast',
        '2 tsp Sugar',
        '1 tsp Salt',
        '2 tablespoons Vegetable Oil',
        '6 cups Flour',
        '2 1/2 cups Warm Water',
      ],
      steps: [
        'Sift half the flour, mix with salt and yeast in a large mixing bowl, and slowly add warm water until the mixture forms a stiff dough. Add more sifted flour until you have a stiff enough dough to knead.',
        'Lightly flour the work surface, knead the dough for 10 minutes until it is smooth and elastic, and then place it in a greased bowl. Now place the bowl warmly for 40-50 minutes until it has doubled. You know the dough is ready when you poke a finger, and the indentation remains.',
        'Preheat oven to 425 degrees F or 220 degrees C.',
        'Now divide the dough into 12 equal portions, roll each into a fist size ball, and place on a greased baking sheet. Now place in a warm place again for a further 40 minutes or again until the dough has doubled in size.',
        'Now place in the oven’s center and bake for 25-30 minutes until golden brown rolls sound hollow when tapped.',
      ],
      prepMinutes: 30,
    ),
    Recipe(
