    Recipe(
      id: 'm52967',
      name: 'Home-made Mandazi',
      description: 'Kenyan Breakfast dish.',
      ingredientKeywords: ['self-raising flour', 'sugar', 'eggs', 'milk'],
      categories: ['Bakery', 'Dairy'],
      ingredients: [
        '750g Self-raising Flour',
        '6 tablespoons Sugar',
        '2 Eggs',
        '1 cup Milk',
      ],
      steps: [
        'This is one recipe a lot of people have requested and I have tried to make it as simple as possible and I hope it will work for you. Make sure you use the right flour which is basically one with raising agents. Adjust the amount of sugar to your taste and try using different flavours to have variety whenever you have them.',
        'You can use Coconut milk instead of regular milk, you can also add desiccated coconut to the dry flour or other spices like powdered cloves or cinnamon.',
        'For “healthy looking” mandazis do not roll the dough too thin before frying and use the procedure I have indicated above.',
        'Mix the flour,cinnamon and sugar in a suitable bowl.',
        'In a separate bowl whisk the egg into the milk',
        'Make a well at the centre of the flour and add the milk and egg mixture and slowly mix to form a dough.',
        'Knead the dough for 3-4 minutes or until it stops sticking to the sides of the bowl and you have a smooth surface.',
        'Cover the dough with a damp cloth  and allow to rest for 15 minutes.',
        'Roll the dough on a lightly floured surface into a 1cm thick piece.',
        'Using a sharp small knife, cut the dough into the desired size setting aside ready for deep frying.',
        'Heat your oil in a suitable pot and gently dip the mandazi pieces to cook until light brown on the first side then turn to cook on the second side.',
        'Serve them warm or cold',
      ],
      prepMinutes: 30,
    ),
    Recipe(
      id: 'm53459',
      name: 'Chicken and Potato Roti',
      description: 'Chicken dish.',
      ingredientKeywords: ['flour', 'shortening', 'salt', 'water', 'chicken breast', 'parsley', 'thyme', 'jerk', 'salt', 'sugar', 'black pepper', 'onion', 'garlic', 'scotch bonnet', 'potatoes'],
      categories: ['Bakery', 'Meat'],
      ingredients: [
        '1 lb Flour',
        '3  tablespoons Shortening',
        'Pinch Salt',
        'Splash Water',
        '6 Chicken Breast',
        'Pinch Parsley',
        'Pinch Thyme',
        'Pinch Jerk',
        'Pinch Salt',
        'Pinch Sugar',
        'Pinch Black Pepper',
        '2 large Onion',
        '4 cloves Garlic',
        '1 Scotch Bonnet',
        '1/2 lb Potatoes',
      ],
      steps: [
        'Add a pint of chicken stock to the simmer and put three tablespoons of sugar into a large saucepan on high; cook until the sugar caramelizes, then add the cubed chicken breasts and stir until the chicken browns.',
        'Add chopped onions, garlic, parsley, thyme, jerk seasoning, salt, and the whole scotch bonnet pepper – do not cut up the pepper! Reduce the heat to low and let this simmer for 25 minutes.',
        'In a large mixing bowl, sift the flour, and add a pinch of salt to taste.',
        'Now add the first tablespoon of shortening, and with your fingers, rub the flour into the shortening until it forms a breadcrumb-like consistency.',
        'Then add the second tablespoon of shortening and rub against the flour until it looks like breadcrumbs.',
        'Now add the third tablespoon of shortening and repeat the process.',
        'You should by now have used all the flour. Your bowl should be all breadcrumb-like; if you still have fresh flour, use another tablespoon of shortening until your fresh flour is all used up.',
        'Add a small amount of water and mix with a butter knife; keep adding small amounts until your mixture forms a soft dough.',
        'Now dust your surface with flour and roll out your pastry; you want to roll wafer-thin rounds – this mixture should make at least 12 roti skins.',
        'Cover with a tea towel while returning to the pot.',
        'Now peel the potatoes and cube them into small bite-size pieces.',
        'After 25 minutes of simmering, add 1/2 pint of water and the potatoes to the pool.',
        'Now cover and cook for 30 minutes on low heat.',
        'Turn a flat baking tray upside down, lightly cover with foil, and place on the stovetop on high; cook each roti skin for 1 minute on each side until brown but not crisp.',
        'Now pile up your cooked roti skins, remove the pot after 30 minutes, and remove the whole scotch bonnet.',
        'Take the entire pot to the table with a pile of plates; each person assumes the roti skin, lays it flat on the scale, spoons some filling into the middle of the roti skin, and folds around the filling eats enjoy.',
      ],
      prepMinutes: 30,
    ),
