    Recipe(
      id: 'm53257',
      name: 'kofta burgers',
      description: 'Turkish Lamb dish.',
      ingredientKeywords: ['lamb', 'onion', 'garlic bulb', 'garam masala', 'coriander', 'chilli sauce', 'pita bread', 'tomato', 'red cabbage', 'red onions', 'yogurt'],
