    Recipe(
      id: 'm53305',
      name: 'Braised stuffed cabbage',
      description: 'Polish Vegetarian dish.',
      ingredientKeywords: ['cabbage leaves', 'olive oil', 'onion', 'rosemary', 'celery', 'basmati rice', 'cooked chestnut', 'cranberry', 'vegetable stock', 'balsamic vinegar', 'clear honey'],
