    Recipe(
      id: 'm52997',
      name: 'Beef Banh Mi Bowls with Sriracha Mayo, Carrot & Pickled Cucumber',
      description: 'Vietnamese Beef dish.',
      ingredientKeywords: ['rice', 'onion', 'lime', 'garlic clove', 'cucumber', 'carrots', 'ground beef', 'soy sauce'],
