      description: 'Russian Vegetarian dish.',
      ingredientKeywords: ['unsalted butter', 'onion', 'cabbage', 'carrots', 'celery', 'bay leaf', 'vegetable stock', 'potatoes', 'tomatoes', 'sour cream', 'dill'],
