      name: 'Baghlaw-e-Khanagi',
      description: 'Dessert dish.',
      ingredientKeywords: ['flour', 'eggs', 'milk', 'vegetable oil', 'baking powder', 'ground walnuts', 'cardamom', 'sugar', 'water'],
