      name: 'Beef Dumpling Stew',
      description: 'British Beef dish.',
      ingredientKeywords: ['olive oil', 'butter', 'beef', 'plain flour', 'garlic', 'onions', 'celery', 'carrots', 'leek', 'swede', 'red wine', 'beef stock', 'bay leaf', 'thyme', 'parsley', 'plain flour', 'baking powder', 'suet', 'water'],
