    Recipe(
      id: 'm52810',
      name: 'Osso Buco alla Milanese',
      description: 'Italian Miscellaneous dish.',
      ingredientKeywords: ['veal', 'flour', 'olive oil', 'butter', 'onion', 'carrots', 'celery', 'fennel', 'garlic', 'orange zest', 'marjoram', 'bay leaf', 'dry white wine', 'chicken stock', 'tomatoes', 'parsley', 'garlic', 'lemon zest'],
      categories: ['Bakery', 'Dairy'],
      ingredients: [
