    Recipe(
      id: 'm52795',
      name: 'Chicken Handi',
      description: 'India Chicken dish.',
      ingredientKeywords: ['chicken', 'onion', 'tomatoes', 'garlic', 'ginger paste', 'vegetable oil', 'cumin seeds', 'coriander seeds', 'turmeric powder', 'chilli powder', 'green chilli', 'yogurt', 'cream', 'fenugreek', 'garam masala', 'salt'],
      categories: ['Dairy', 'Meat'],
      ingredients: [
