      description: 'India Vegetarian dish.',
      ingredientKeywords: ['toor dal', 'water', 'salt', 'turmeric', 'ghee', 'chopped tomatoes', 'cumin seeds', 'mustard seeds', 'bay leaf', 'green chilli', 'ginger', 'cilantro', 'red pepper', 'salt', 'sugar', 'garam masala'],
