    Recipe(
      id: 'm53316',
      name: 'Beetroot pancakes',
      description: 'Ukrainian Dessert dish.',
      ingredientKeywords: ['beetroot', 'milk', 'self-raising flour', 'baking powder', 'maple syrup', 'vanilla extract', 'egg', 'butter', 'frozen mixed berries', 'blackcurrant jam', 'greek yogurt'],
