    Recipe(
      id: 'm53469',
      name: 'Beef pumpkin Stew',
      description: 'Beef dish.',
      ingredientKeywords: ['beef', 'all purpose flour', 'butter', 'onion', 'garlic', 'beef stock', 'pumpkin puree', 'worcestershire sauce', 'kosher salt', 'black pepper', 'potatoes', 'carrots', 'thyme'],
