      description: 'India Chicken dish.',
      ingredientKeywords: ['chicken', 'basmati rice', 'water', 'onion', 'garlic', 'green chilli', 'salt', 'oil', 'turmeric powder', 'coriander', 'cardamom', 'cloves', 'cinnamon', 'pepper', 'bay leaf'],
