        '1 teaspoon Coriander',
        '½ tbsp Cardamom',
        '¼ teaspoon Cloves',
        '1/2 tsp Cinnamon',
        '1 tsp Pepper',
        '2 Bay Leaf',
      ],
      steps: [
        'Clean and cut the chicken; marinate briefly with salt, turmeric and a little oil.',
        'Rinse and soak basmati rice 20–30 minutes.',
